// The council logo (assets/council-logo.png) as a data URL, generated from that file.
// The report header uses this so the PNG export never has to fetch the image: a fetched image fails
// when the app is opened as a file (file://) or the assets folder is missing, and html-to-image then
// aborted the export with "[object Event]". Regenerate this file if the logo changes.
window.COUNCIL_LOGO = "data:image/png;base64,";
